// lib/api/student-note-safe.js
// PR-4c-4d B1 fix — defense-in-depth scrubber so coach-internal Damon Note sections
// never reach the student.
//
// Primary source-of-truth: /api/note (student path) reads sessions.notebook_page
// (Vivi-warm version generated by generateNotebookPage's Sonnet prompt). The
// notebook prompt is designed to keep coach-internal terms out, but Sonnet drift
// happens — these helpers belt-and-suspenders the boundary.
//
// Also exposes containsForbiddenContent() for assertions / monitoring: if it
// returns true for a value about to go to a student, log loudly + sanitize.
//
// FORBIDDEN markers (the Damon Note section headers + coach-only tool/layer terms):

const FORBIDDEN_SECTION_MARKERS = Object.freeze([
  '【今天的模式】',
  '【關鍵句】',
  '【深度層次】',
  '【SC 觀察】',
  '【還沒碰到的】',
  '【明天的入口】',
  '【Day 1-6 採集追蹤】',
  '【Scope 證據】',
  '【賦予新角色狀態】',
  '【確定類別 + Scope】',
  '【Transfer 結果】',
  '【微證據 + 反例預演結果】',
  '【宣言】',
]);

// 工具一/二/三/四 (v4 tool pool names) + the 2A/2B/2C tool-pool tags
const FORBIDDEN_TOOL_REGEX = /(工具[一二三四1234])|(2[ABC]\s?(SC 池|Reactive 池|Belief 池))/u;
// "Layer 1" through "Layer 5" / "L1-L5" — the explicit layer numbering
const FORBIDDEN_LAYER_REGEX = /(Layer\s?[1-5]\b)|(\bL[1-5]\b)/u;

export const _internal = {
  FORBIDDEN_SECTION_MARKERS,
  FORBIDDEN_TOOL_REGEX,
  FORBIDDEN_LAYER_REGEX,
};

/**
 * Strip coach-internal content from a piece of text that's about to go to a student.
 * Conservative — drops whole lines containing forbidden markers / tool names /
 * layer numbers. Collapses runs of blank lines that result.
 *
 * @param {string} text
 * @returns {string} cleaned text (empty string for nullish input)
 */
export function sanitizeStudentNote(text) {
  if (typeof text !== 'string' || text.length === 0) return '';
  const lines = text.split(/\r?\n/);
  const out = [];
  let inForbiddenSection = false;
  for (const line of lines) {
    const trimmed = line.trim();
    // Start of a forbidden 【...】 section → swallow it AND its body
    if (FORBIDDEN_SECTION_MARKERS.some(m => trimmed.startsWith(m))) {
      inForbiddenSection = true;
      continue;
    }
    // A new section header (✦/【】/---) ends the forbidden-section run
    if (trimmed.startsWith('✦') || /^【.+】/.test(trimmed) || trimmed.startsWith('---')) {
      inForbiddenSection = false;
    }
    // A blank line also ends the forbidden section (paragraph break in Damon Note
    // convention). Skip the blank line itself when it's the section terminator —
    // the join+collapse below restores normal paragraph spacing between kept text.
    if (trimmed === '' && inForbiddenSection) {
      inForbiddenSection = false;
      continue;
    }
    if (inForbiddenSection) continue;
    // Line-level scrubs even outside a forbidden section
    if (FORBIDDEN_TOOL_REGEX.test(line)) continue;
    if (FORBIDDEN_LAYER_REGEX.test(line)) continue;
    out.push(line);
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

/**
 * Quick predicate — does `text` contain anything we promised never to show
 * a student? Use for assertions / observability.
 *
 * @param {string} text
 * @returns {boolean}
 */
export function containsForbiddenContent(text) {
  if (typeof text !== 'string' || text.length === 0) return false;
  for (const m of FORBIDDEN_SECTION_MARKERS) {
    if (text.includes(m)) return true;
  }
  if (FORBIDDEN_TOOL_REGEX.test(text)) return true;
  if (FORBIDDEN_LAYER_REGEX.test(text)) return true;
  return false;
}
